import { Feather } from '@expo/vector-icons';
import { router } from 'expo-router';
import React, { useState } from 'react';
import { FlatList, Pressable, StyleSheet, Text, View } from 'react-native';
import { SafeAreaView, useSafeAreaInsets } from 'react-native-safe-area-context';
import notices from '../src/data/ossNotices.json';
import { useSettings } from '../src/store/settings';
import { MIN_TOUCH, RADIUS, SPACE, TYPE, useTheme } from '../src/theme';

// S11 – open-source licences. Data generated by scripts/gen-oss-notices.mjs
// (src/data/ossNotices.json, never edited by hand; `npm run check` fails when out of date).

type Notice = { name: string; version: string; license: string; text: number | null; repo: string | null };
const PACKAGES = notices.packages as Notice[];
const TEXTS = notices.texts as string[];

export default function LicensesScreen() {
  const { t } = useSettings();
  const c = useTheme();
  const insets = useSafeAreaInsets();
  const [open, setOpen] = useState<string | null>(null);

  return (
    <SafeAreaView edges={['top']} style={[styles.root, { backgroundColor: c.bg }]}>
      <View style={styles.header}>
        <Pressable
          onPress={() => router.back()}
          hitSlop={4}
          accessibilityRole="button"
          accessibilityLabel={t('common.back')}
          style={({ pressed }) => [styles.back, { backgroundColor: c.surface, opacity: pressed ? 0.7 : 1 }]}
        >
          <Feather name="chevron-left" size={22} color={c.text} />
        </Pressable>
        <Text style={[TYPE.heading, styles.flex, { color: c.text }]} accessibilityRole="header" numberOfLines={1}>
          {t('licenses.title')}
        </Text>
      </View>
      <FlatList
        data={PACKAGES}
        keyExtractor={(p) => `${p.name}@${p.version}`}
        contentContainerStyle={[styles.list, { paddingBottom: insets.bottom + SPACE.xl }]}
        ListHeaderComponent={<Text style={[TYPE.body, styles.intro, { color: c.textMuted }]}>{t('licenses.intro', { n: PACKAGES.length })}</Text>}
        initialNumToRender={20}
        renderItem={({ item }) => {
          const key = `${item.name}@${item.version}`;
          const expanded = open === key;
          return (
            <View style={[styles.item, { backgroundColor: c.surface }]}>
              <Pressable
                onPress={() => setOpen(expanded ? null : key)}
                accessibilityRole="button"
                accessibilityState={{ expanded }}
                style={styles.itemHead}
              >
                <View style={styles.flex}>
                  <Text style={[TYPE.bodyStrong, { color: c.text }]} numberOfLines={1}>
                    {item.name}
                  </Text>
                  <Text style={[TYPE.caption, { color: c.textMuted }]}>
                    {item.version} · {item.license}
                  </Text>
                </View>
                <Feather name={expanded ? 'chevron-up' : 'chevron-down'} size={18} color={c.textMuted} />
              </Pressable>
              {expanded && (
                <View style={[styles.text, { borderColor: c.border }]}>
                  {item.repo && <Text style={[TYPE.caption, { color: c.textMuted }]}>{item.repo}</Text>}
                  <Text style={[styles.mono, { color: c.text }]} selectable>
                    {item.text !== null ? TEXTS[item.text] : t('licenses.noText', { license: item.license })}
                  </Text>
                </View>
              )}
            </View>
          );
        }}
      />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1 },
  flex: { flex: 1 },
  header: { flexDirection: 'row', alignItems: 'center', gap: SPACE.md, paddingHorizontal: SPACE.lg, paddingVertical: SPACE.sm },
  back: { width: MIN_TOUCH, height: MIN_TOUCH, borderRadius: MIN_TOUCH / 2, alignItems: 'center', justifyContent: 'center' },
  list: { paddingHorizontal: SPACE.lg, gap: SPACE.sm, width: '100%', maxWidth: 760, alignSelf: 'center' },
  intro: { marginBottom: SPACE.sm },
  item: { borderRadius: RADIUS.md, paddingHorizontal: SPACE.md },
  itemHead: { flexDirection: 'row', alignItems: 'center', gap: SPACE.sm, minHeight: MIN_TOUCH + 4 },
  text: { borderTopWidth: StyleSheet.hairlineWidth, paddingVertical: SPACE.md, gap: SPACE.sm },
  mono: { fontSize: 11, lineHeight: 16 },
});
